import { readFile } from 'node:fs/promises';
import { join } from 'node:path';
import { themeEmojiName } from './guildSettingsContract.js';
import { currentThemePreset } from './themeContext.js';

// The name→ID map comes from `resources/emoji_replacement/emoji-ids.json` (generated by `scripts/upload-emojis.ts`);
// the bot's `appEmojiManager` then supplements it via `setAppEmojiIdMap()` after boot. An empty load yields the unicode fallback.
// Standard fallbacks live only in APP_EMOJI_FALLBACKS so one name never gets different fallbacks; pass `emoji('name', fallback)` only for names missing there.

type EmojiIdMap = Record<string, string>;

